package driver

import (
	"fmt"
	"strings"

	sitter "github.com/tree-sitter/go-tree-sitter"

	"github.com/Lyra-Language/lyra/pkg/analyzer/collector"
	"github.com/Lyra-Language/lyra/pkg/parser"
	"github.com/Lyra-Language/lyra/pkg/types"
)

// fixedImplsFile names the unit generated by addFixedImpls in a location.
const fixedImplsFile = "<fixed-point impls>"

// addFixedImpls gives each `fixed<I, F>` the program wrote the prelude's trait impls, which
// the prelude writes out for every integer width and cannot write for the 116 formats there
// are. It is a file of the prelude's module, in the prelude's own words, so `a.min(b)`, a
// `where t: Ord` and a `"${show(v)}"` reach a fixed value by the ordinary routes and nothing
// downstream knows these impls were not written by hand.
//
// The tree it answers has to stay open until the collector has finished.
func addFixedImpls(c *collector.Collector, prelude string, formats []types.FixedFormat) (*sitter.Tree, error) {
	if len(formats) == 0 {
		return nil, nil
	}
	var text strings.Builder
	fmt.Fprintf(&text, "module %s\n", prelude)
	for _, f := range formats {
		name := fmt.Sprintf("fixed<%d, %d>", f.Integer, f.Fraction)
		fmt.Fprintf(&text, `impl Add for %[1]s { (_+_) = pure (self, o) => self + o }
impl Sub for %[1]s { (_-_) = pure (self, o) => self - o }
impl Mul for %[1]s { (_*_) = pure (self, o) => self * o }
impl Div for %[1]s { (_/_) = pure (self, o) => self / o }
impl Arithmetic for %[1]s
impl Ord for %[1]s { compare = pure noalloc (self, other) => self <=> other }
impl Show for %[1]s { show = pure (self) => "${self}" }
impl Signed for %[1]s {
  is_negative = pure (self) => self < 0
  abs = pure (self) => if self.is_negative() { -self } else { self }
}
`, name)
	}
	source := text.String()
	tree, err := parser.Parse(source)
	if err != nil {
		return nil, err
	}
	c.AddFile(tree.RootNode(), []byte(source), fixedImplsFile, prelude)
	return tree, nil
}
